// Diagnostic host only: the same admitted Int64 feature is enabled for
// both complete stock and candidate modules, without changing DeviceInfo.
VkPhysicalDeviceFeatures supported{};
vkGetPhysicalDeviceFeatures(device->physical_, &supported);
if (supported.shaderInt64 != VK_TRUE) {
    return Fail(ErrorDomain::kDevice, "open diagnostic Int64 device",
                "selected physical device does not support shaderInt64");
}
VkPhysicalDeviceFeatures enabled{};
enabled.shaderFloat64 = device->info_.supports_fp64 ? VK_TRUE : VK_FALSE;
enabled.shaderInt64 = VK_TRUE;
